import React, { useEffect, useRef, useState } from 'react';

/**
 * Original DanGG table effects: play-once animated WebP files generated by
 * tools/original-assets/effects.mjs. Durations must match that generator.
 */
export const FX_EFFECTS = Object.freeze({
  spin_intro: { src: '/assets/fx/spin_intro.webp', durationMs: 2500 },
  spin_win: { src: '/assets/fx/spin_win.webp', durationMs: 2000 },
  mystery_box: { src: '/assets/fx/mystery_box.webp', durationMs: 2500 },
  win_effect: { src: '/assets/fx/win_effect.webp', durationMs: 1500 },
  chip_shuffle: { src: '/assets/fx/chip_shuffle.webp', durationMs: 2000 },
});

export type FxName = keyof typeof FX_EFFECTS;

/** Small margin so the final (transparent) frame is reached before the overlay unmounts. */
const END_HOLD_MS = 150;
/** Same quick dismissal the old SWF overlay used when an effect failed to load. */
const FAILED_CLEAR_MS = 1200;

const fxBytes = new Map<string, Promise<Blob>>();

/** Fetch an effect once; each play then gets its own object URL so the animation restarts from frame one. */
function loadFx(src: string): Promise<Blob> {
  const cached = fxBytes.get(src);
  if (cached) return cached;
  const request = fetch(src).then((res) => {
    if (!res.ok) throw new Error(`FX ${src} failed: HTTP ${res.status}`);
    return res.blob();
  });
  fxBytes.set(src, request);
  request.catch(() => fxBytes.delete(src));
  return request;
}

/** Transparent overlay that plays one table effect, then calls onDone. */
export function FxEffect({ name, onDone, className = '' }: { name: FxName; onDone: () => void; className?: string }) {
  const { src, durationMs } = FX_EFFECTS[name];
  const [url, setUrl] = useState<string | null>(null);
  const doneRef = useRef(onDone);
  doneRef.current = onDone;
  const timer = useRef(0);

  const finishIn = (ms: number) => {
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => doneRef.current(), ms);
  };

  useEffect(() => {
    let cancelled = false;
    let objectUrl: string | null = null;
    loadFx(src)
      .then((blob) => {
        if (cancelled) return;
        objectUrl = URL.createObjectURL(blob);
        setUrl(objectUrl);
      })
      .catch((err) => {
        console.warn('FX effect failed', err);
        if (!cancelled) finishIn(FAILED_CLEAR_MS);
      });
    return () => {
      cancelled = true;
      window.clearTimeout(timer.current);
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      setUrl(null);
    };
  }, [src]);

  return (
    <div className={'fx-effect ' + className} aria-hidden="true">
      {url && (
        <img
          src={url}
          alt=""
          draggable={false}
          onLoad={() => finishIn(durationMs + END_HOLD_MS)}
          onError={() => finishIn(FAILED_CLEAR_MS)}
        />
      )}
    </div>
  );
}
